### Clean Architecture Refactoring

#### 1. Domain (`src/domain/ChatMessage.ts`)
```typescript
export class ChatMessage {
  private constructor(
    public readonly room: string,
    public readonly author: string,
    public readonly text: string,
  ) {}

  static create(room: string, author: string, text: string): ChatMessage {
    if (text.length === 0 || text.length > 500) throw new Error('Message length is not allowed');
    if (/https?:\/\//i.test(text)) throw new Error('Links are not allowed');
    return new ChatMessage(room, author, text);
  }
}
